import fs from 'node:fs'; import path from 'node:path';
const GEN = path.resolve('machtzev/generator');
const { perukToSpec } = await import(path.join(GEN, 'peruk.mjs'));
for (const f of fs.readdirSync(GEN + '/peruks').filter((x) => x.endsWith('.md')).sort()) {
  const ns = f.replace(/\.md$/, '').replace(/-/g, '');
  const { spec, node } = perukToSpec(fs.readFileSync(GEN + '/peruks/' + f, 'utf8'), ns);
  const disc = (spec.split('\n').find((l) => l.startsWith('תוכן הסתייגות:')) || '').replace('תוכן הסתייגות:', '').trim();
  const hits = node.classes.filter((c) => disc.includes(c));
  const dash = spec.split('\n').find((l) => l.startsWith('לוח בקרה'));
  console.log(ns, '| classes:', JSON.stringify(node.classes), '| disc:', disc.slice(0, 70), '| HITS:', JSON.stringify(hits), '|', dash);
}
EOF
